INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62035089', 62035089, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Quality Analyst Pengembangan Produk dan Layanan April - Desember 2 #3', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99000000, 'March 2026', 'APBD', 1, 1, '1 Orang x 9 Bulan', '1. Melakukan pengujian fungsional backend API sesuai dengan kebutuhan, serta memastikan bahwa fungsi-fungsi backend dapat beroperasi dengan benar sesuai dengan spesifikasi; 2. Melakukan pengujian data pada database, serta memverifikasi integritas dan akurasi data yang disimpan di dalam database; 3. Melakukan pengujian kesesuaian frontend UI dengan desain, serta menjamin bahwa antarmuka pengguna sesuai dengan desain yang telah ditetapkan; 4. Melakukan pengujian fungsional dan kesesuaian flow sistem pada aplikasi, serta memastikan bahwa aplikasi beroperasi dengan baik sesuai dengan alur yang telah ditentukan; 5. Membuat skenario pengujian sesuai dengan flow dan desain aplikasi yang mencakup berbagai kondisi untuk memastikan kehandalan aplikasi; 6. Melakukan pengujian aplikasi pada environment development, staging, dan production, baik pada basis website ataupun mobile, untuk menjamin konsistensi dan kualitas aplikasi di berbagai platform di setiap tahapan pengembangan; 7. Melakukan performance test aplikasi, mengukur dan memastikan kinerja aplikasi dalam menghadapi beban kerja yang berbeda; 8. Melakukan automation test dari sisi backend dan frontend dengan menggunakan alat otomatisasi untuk meningkatkan efisiensi dan akurasi pengujian; 9. Mendokumentasikan error, bugs, atau isu dari hasil pengujian, serta menyusun laporan yang jelas untuk memudahkan pemahaman dan perbaikan; dan 10. Melakukan UAT dengan tim terkait untuk memastikan bahwa aplikasi memenuhi standar kualitas yang diinginkan sebelum rilis ke pengguna akhir.', 'Tenaga Ahli Muda Spesifikasi: S1 Pengalaman Minimal 2 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 561829);
