INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62524774', 62524774, 'analyze_legacy', 'Kab. Kutai Kartanegara', 'kabkota', 'Badan Perencanaan Pembangunan Daerah', 'Belanja Jasa Tenaga Kebersihan Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Kutai Kartanegara (Kab.)', 1010880000, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Badan Perencanaan Pembangunan Daerah merupakan Instansi Pemerintah yang bergerak di bidang perencanaan pembangunan daerah. Oleh karena itu, pekerjaan yang tidak berhubungan langsung dengan perencanaan pembangunan daerah seperti pemeliharaan gedung bangunan /jasa kebersihan di pandang perlu untuk dikelolah melalui penyedia jasa kebersihan, dengan menyerahkan pengelolaan kebersihan gedung Kantor Badan Perencanaan Pembangunan Daerah kepada Jasa penyedia tenaga kebersihan, karena kebersihan gedung Kantor Badan Perencanaan Pembangunan Daerah adalah faktor terpenting untuk menciptakan kenyamanan kerja dan sebagai kebutuhan utama bagi Badan Perencanaan Pembangunan Daerah dalam mendukung aktifitas seluruh ASN. Untuk mewujudkan kondisi tersebut diperlukan kesiapan dan perencanaan yang baik agar terpenuhinya jasa penyedia pengelola kebersihan gedung Kantor Badan Perencanaan Pembangunan Daerah yang benar-benar handal dan profesional dalam bidang tersebut, dan dapat tercermin dari kondisi umum lingkungan gedung Kantor Badan Perencanaan Pembangunan Daerah yang bersih dan sehat.', '1. Pemeliharaan Kebersihan (Cleaning Service) Program kerja pemeliharaan kerja gedung meliputi program kerja harian, mingguan, bulanan dan tahunan yang bertujuan untuk memelihara kebersihan gedung yang meliputi kebersihan publik area, office area dan toilet area serta kelengkapannya. 2. Pemeliharaan dan Perawatan (Hygiene Service) Program kerja hygiene service meliputi program pemeliharaan perawatan untuk pengharum ruangan dan anti septik yang memberikan kesan bersih, harum dan sehat meliputi ruang kantor lobby, lift, ruang rapat maupun toilet yang disesuaikan dengan keadaan fungsi ruangan. 3. Program General Cleaning Program pemeliharaan kebersihan yang dilakukan secara umum untuk sebuah gedung dilakukan untuk tetap menjaga keindahan kenyamanan maupun performance gedung yang dikerjakan pada hari-hari tertentu atau pada hari libur yang bertujuan untuk mengangkat atau mengupas kotoran pada suatu objek tertentu, seperti pada lantai, kaca bagian dalam, dinding, toilet dan perlengkapan, peralatan dan aksesoris gedung bangunan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 561958);
