INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63087231', 63087231, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Pengawasan Penyelenggaraan Jalan / Jembatan Wilayah 82', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 100000000, 'January 2026', 'APBD', 1, 1, '1 Paket', '1. Pengawasan pekerjaan-pekerjaan yang berhubungan dengan kegiatan selama masa pelaksanaan fisik 2. mengidentifikasi setiap persoalan yang mungkin terjadi dilapangan sehubungan dengan aktivitas kontraktor 3. membuat rekomendasi dalam memecahkan persoalan tersebut 4. membentuk tim pengawas yang berkedudukan di lokasi pekerjaan 5. konsultan harus membentuk tim yang mempunyai tugas dalam jasa pelayanan yang terdiri Pengawasan Teknis 6. melakukan jasa konsultasi untuk supervisi kontruksi secara profesional sesuai dengan prinsip-prinsip serta kebijakan-kebijakan yang diterapkan DPUTR Kabupaten Bandung 7. menyediakan layanan jasa konsultansi dan sepenuhnya membantu pihak pengguna jasa sebagaimana diatur dalam dokumen kontrak', '• Mengawasi Pelaksanaan Pekerjaan Fisik telah sesuai dengan perencanaan dan mengikuti standar prosedur yang berlaku untuk tercapainya mutu pekerjaan fisik. • Terselesainya penanganan atas permasalahan – permasalahan yang terjadi dilapangan baik yang sifatnya umum atau yang memiliki tingkat problematika yang tinggi sehingga tercapai tingkat pelayanan yang diinginkan (umur rencana dapat tercapai).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 562767);
