INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63087351', 63087351, 'analyze_legacy', 'Kab. Madiun', 'kabkota', 'Dinas Komunikasi dan Informatika', 'Belanja Sewa Aset Tidak Berwujud-Lisensi dan Franchise', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Madiun (Kab.)', 60000000, 'January 2026', 'APBD', 1, 0, '1 Paket', 'Lisensi Fortinet Firewall; Lisensi ntopng (High-Speed Web-based Traffic Analysis and Flow Collection); Lisensi CloudFlare Pro;', 'C-10-F100F-950-02-12 Unified Threat Protection (UTP) (IPS, Advanced Malware Protection, Application Control, Web & Video Filtering, Antispam Service, and FortiCare Premium); 1.Menyortir lalu lintas jaringan berdasarkan berbagai kriteria. 2.Menampilkan lalu lintas jaringan dan host aktif secara real-time. 3.Menghasilkan laporan jangka panjang untuk berbagai metrik jaringan. 4.Menampilkan "top talkers" (pengirim/penerima data terbanyak). 5.Memantau dan melaporkan throughput langsung, latensi jaringan dan aplikasi, waktu perjalanan pulang pergi (RTT), statistik TCP (retransmisi, paket tidak berurutan, paket hilang), serta jumlah byte dan paket yang dikirim. 6.Menyimpan statistik lalu lintas secara permanen di disk untuk eksplorasi di masa mendatang dan analisis pasca-insiden. 7.Melakukan geolokasi dan menampilkan host pada peta geografis. 8.Mendeteksi protokol aplikasi Layer-7 (seperti Facebook, YouTube, BitTorrent, dll.) dengan teknologi nDPI (ntop Deep Packet Inspection). 9.Menganalisis lalu lintas IP dan menyortirnya berdasarkan sumber/tujuan. 10.Melaporkan penggunaan protokol IP yang dikelompokkan berdasarkan jenis protokol. 11.Menghasilkan statistik lalu lintas jaringan dalam format HTML5/AJAX. 12.Dukungan penuh untuk IPv4 dan IPv6.; 1.Melindungi dari serangan umum, termasuk kerentanan OWASP, dengan WAF 2.Melindungi dari ancaman zero-day dengan WAF 3.Mendeteksi dan menantang bot yang mudah terdeteksi 4.Memuat aset utama situs secara prioritas 5.Caching cerdas untuk WordPress 6.Optimasi gambar dengan sekali klik 7.Analitik cache untuk optimasi CDN 8.Dan, semua fitur dalam paket Gratis Hingga 155 Aturan Cloudflare 20 Aturan WAF;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 562826);
