INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62524433', 62524433, 'analyze_legacy', 'Kab. Kutai Kartanegara', 'kabkota', 'Badan Perencanaan Pembangunan Daerah', 'Belanja Jasa Tenaga Keamanan Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Kutai Kartanegara (Kab.)', 990120000, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Belanja Jasa Tenaga Keamanan ini merupakan kegiatan rutin yang dilakukan untuk mengelola keamanan dan ketertiban di lingkungan Badan Perencanaan Pembangunan Daerah, dengan terselenggaranya kegiatan pengadaan Jasa Keamanan ini di harapkan tercapai tujuan sebagai berikut : 1. Menciptakan keamanan dan kenyamanan lingkungan sehingga dapat meningkatkan kinerja ASN di lingkungan Badan Perencanaan Pembangunan Daerah. 2. Menciptakan lingkungan Badan Perencanaan Pembangunan Daerah yang aman dan kondusif.', 'Lingkup pekerjaan penyediaan jasa tenaga keamanan kantor Badan Perencanaan Pembangunan Daerah sebagai berikut : 1. Pemeliharaan dan penjagaan keamanan menyeluruh pada lingkungan Kantor Badan Perencanaan Pembangunan Daerah; 2. Pemeliharaan dan penjagaan keamanan menyeluruh pada gedung di lingkungan Kantor Badan Perencanaan Pembangunan Daerah; 3. Pemeliharaan dan penjagaan keamanan pada bangunan/aset Badan Perencanaan Pembangunan Daerah lainnya; 4. Pemeliharaan dan penjagaan keamanan kediaman/rumah dinas pimpinan Badan Perencanaan Pembangunan Daerah; 5. Penjagaan keamanan acara/kegiatan pimpinan; 6. Penjagaan keamanan acara/kegiatan Badan Perencanaan Pembangunan Daerah; 7. Pemberian laporan kondisi keamanan dan ketertiban; 8. Pemberian masukan teknis terkait keamanan dan ketertiban jika diperlukan; 9. Pelaksanaan tugas lain yang diperintahkan oleh Pejabat Pembuat Komitmen (PPK) terkait pekerjaan keamanan dan ketertiban; dan 10. Penyediaan peralatan dan perlengkapan sesuai kebutuhan untuk melaksanakan pekerjaan ini sesuai spesifikasi teknis yang tetap dipakai.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 563294);
