INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62524750', 62524750, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Pemetaan Aplikasi Manajemen Pemerintahan Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 67032000, 'December 2025', 'APBD', 1, 1, '4 OB', 'Analis Sistem • melakukan kajian bagaimana proses bisnis (business process) aplikasi – aplikasi yang sudah (penambahan modul) dan akan berjalan. Kajian dilakukan dengan cara terlibat langsung dan mengamati workflow yang sedang berjalan, dan melakukan wawancara kepada narasumber dan user yang menjalankan workflow; • melakukan kajian dan analisa sistem terhadap ketentuan-ketentuan, kriteria dan penentuan aplikasi yang akan dikembangkan sesuai dengan peraturan/undang-undang yang berlaku; • membuat flowchart dari hasil analisa sistem; • memastikan semua tahapan dalam pembuatan/pengembangan sistem berjalan sesuai dengan requirements yang dibuat; • membuat laporan hasil analisa sistem dan laporan user requirements. • Evaluasi terhadap pengembangan (development) terhadap aplikasi yang dikembangkan. • backup dan recovery, membuat perencanaan backup dan recovery untuk mengantisipasi kerusakan-kerusakan yang mungkin terjadi. B. Menyusun laporan dan administrasi kegiatan terkait dengan kegiatan pengembangan aplikasi manajemen pemerintahan.', 'Sistem Analis, Ahli Non SKA/SKK S1 Pengalaman 3 Tahun, S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika dengan kualifikasi: - Pria/Wanita usia maksimal 40 tahun; - Pendidikan S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika; - Memiliki pengalaman kerja lebih dari 3 (tiga) tahun di bidang Teknik Informasi; - Memahami konsep pemrograman berbasiskan obyek (OOP); - Memahami android studio, java native, http request (volley, retrofit); - Menguasai konsep webservices/ web API (REST API); - Terbiasa menggunakan 3rd party libraries; atau - Terbiasa menggunakan framework Code Igniter (CI); - Menguasai bootstrap, html, css, javascript, SQL, PostGreSQL, SQL Server atau Oracle; - Menguasai konsep web service/ webAPI, XML-RPC, SOAP, REST, RESTful; - Dapat mengoperasikan Komputer; - Menguasai aplikasi perkantoran (ms office atau sejenis); - Memiliki Perangkat Kerja dengan platform Android; - Diutamakan memiliki Sertifikat Nasional (BNSP) bidang keahlian Pemrograman; - Bersedia bekerja di lokasi Dinas Komunikasi dan Informatika selama kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 563599);
