INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65961187', 65961187, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'Loka POM di Kabupaten Rejang Lebong', 'PENGADAAN JASA KONSULTAN PERANCANG (REVIEW) PEMBANGUNAN GEDUNG   LAYANAN PUBLIK TAHAP KE-2 DAN FASILITAS PENUNJANG LAYANAN PUBLIK LOKA PENGAWAS OBAT DAN MAKANAN DI KABUPATEN  REJANG LEBONG TAHUN ANGGARAN 2026', 'Jasa Konsultansi', 'Seleksi', 'Bengkulu, Rejang Lebong (Kab.)', 731215000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 731215000 )', 'Tersedianya Layanan Jasa Konsultan Perancang (Review) Pembangunan Gedung Layanan Publik Tahap Ke-2 dan Fasilitas Penunjang Layanan Publik Loka Pengawas Obat Dan Makanan di Kabupaten Rejang Lebong. dalam hal ini berupa Dokumen Perencanaan Teknis terkait pekerjaan Paket Konstruksi dari Pembangunan Gedung Layanan Publik Tahap Ke-2 dan Fasilitas Penunjang Layanan Publik Loka Pengawas Obat Dan Makanan di Kabupaten Rejang Lebong yang memuat aspek Teknis dan Estetika untuk dapat dipergunakan dalam Pekerjaan Kegiatan Konstruksi Fisik terkait', 'Lingkup Pekerjaan yang dimaksudkan dalam KAK ini termasuk diantaranya adalah: 1. Melakukan tinjauan terhadap kondisi eksisting bangunan gedung layanan publik Loka Pengawas Obat dan Makanan di Kabupaten Rejang Lebong denganmengacu kepada rekomendasi hasil pengujian fisik gedung; 2. Melakukan tinjauan terhadap Estimasi Biaya terhadap harga material dan jasadaripada pekerjaan fisik dengan menyelaraskan dokumen perencanaan terakhirdengan kondisi riil yang berada di Kabupaten Rejang Lebong pada tahunanggaran 2026. Apabila material yang dibutuhkan tidak tersedia di KabupatenRejang Lebong, diperhitungkan pula biaya angkut kedalam harga material yangdicantumkan dalam RAB; 3. Melakukan tinjauan terhadap Spesifikasi Teknis dari dokumen perencanaanterakhir dengan kondisi yang dibutuhkan untuk melanjutkan konstruksi tahap ke2; 4. Melakukan Perhitungan terhadap Desain; Spesifikasi Teknis; Daftar KeluaranEstimasi Biaya; Metode Pelaksanaan; Penetapan Tingkat KompleksitasPekerjaan; Kebutuhan Sumber Daya Konstruksi Beserta Rantai PasoknyaMetode Pengoperasioan dan Pemeliharaan Bangunan; Rencana PenjaminanMutu Pekerjaan Konstruksi (RPMK); Rencana Keselamatan Konstruksi (RKK)termasuk rancangan konseptual pelaksanaan keselamatan konstruksi; Sumber Bahan dan Lokasi Material; Perhitungan estimasi TKDN di tahap persiapan pengadaan dan realisasi TKDN di tahap pelaksanaan kontrak pekerjaan konstruksi Sarana Penunjang Layanan Publik termasuk Lanskap dan Drainase; Adapun pekerjaan ini dilaksanakan dengan tahapan sebagai berikut: 1. Tahap konsepsi perancangan; 2. Tahap rancangan detail termasuk rancangan gambar detail (apabila ada perubahan atau penyesuaian berdasarkan rekomendasi hasil pengujian fisik gedung yang dilakukan oleh lembaga independen tersertifikasi) dan rencana anggaran biaya; 3. Tahap tender penyedia jasa pelaksanaan konstruksi; 4. Tahapan Pengawasan Berkala, yakni laporan hasil pengawasan berkala konsultan perencana apabila terjadi perubahan design, dokumen pengawasan berkala, dan lainnya. Jaminan layanan pasca kontrak: Apabila pekerjaan konstruksi nantinya mengalami perubahan pada tahap pelaksanaan kontrak, maka konsultan perancangan akan mengubah seluruh atau sebagian dokumen perancangan sesuai kebutuhan Tanpa Dipungut Biaya Tambahan Tenaga Ahli yang dibutuhkan 1. Team Leader (S2 Teknik Sipil/ S2 Arsitektur, Ahli Madya Teknik Bangunan Gedung, Jenjang 8, Pengalaman 5 Tahun) 2. Ahli Struktur (S2 Teknik Sipil, Ahli Madya Teknik Bangunan Gedung, Jenjang 8, Pengalaman 3 Tahun) 3. Ahli Arsitektur (S1 Arsitektur, Ahli Madya Arsitektur, Jenjang 8, Pengalaman 3 Tahun) 4. Ahli Arsitektur Lanskap (S1 Arsitektur, Ahli Muda Arsitektur Lanskap, Jenjang 7, Pengalaman 3 Tahun) 5. Ahli Elektronika dan Komunikasi Gedung (S1 Teknik Elektro/Teknik Mesin, Ahli Teknik Elektronika dan Telekomunikasi dalam Gedung/ Ahli Muda 6. Elektrikal Konstruksi Bangunan Gedung, Jenjang 7, Pengalaman 3 Tahun) 6. Ahli Muda Mekanikal (S1 Teknik Mesin, Ahli Muda Bidang Keahlian Teknik Mekanikal, Jenjang 7, Pengalaman 3 Tahun) 7. Ahli Estimasi Biaya (S1 Teknik Sipil/Arsitektur/Teknik Arsitektur, Ahli Muda Quantity Surveior, Jenjang 7, Pengalaman 3 Tahun) 8. Ahli Perencanaan Jaringan Drainase (S1 Teknik Sipil atau Teknik Pengairan, Ahli Muda Perencana Jaringan Drainase, Jenjang 7, Pengalaman 3 Tahun) 9. Ahli Teknik Lingkungan (S1 Teknik Lingkungan atau setara, Ahli Muda Teknik Lingkungan bidang Jasa Konstruksi, Jenjang 7, Pengalaman 3 Tahun) 10. Ahli Desain Interior (S1 Arsitektur/Teknik Arsitektur/ Desain Interior, Ahli Muda Desain Interior, Jenjang 7, Pengalaman 3 Tahun) 11. Ahli K3 Konstruksi ( S1 Seluruh Jurusan/ Program Studi Bidang Konstruksi, Ahli Muda Keselamatan Konstruksi, Jenjang 7, Pengalaman 3 Tahun ) Tenaga Pendukung yang dibutuhkan: 1. Asisten Ahli Struktur 2. Asisten Ahli Arsitektur 3. Asisten Ahli Mekanikal 4. Asisten Ahli Elektrikal 5. Asisten Ahli Desain Interior/Desain Grafis 6. Surveyor 7. Operator CAD / Drafter 8. Administrasi kantor / Keuangan / Operator komputer', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 564603);
