INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62528682', 62528682, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS PEMADAM KEBAKARAN', 'Belanja Modal Alat Pemadam Kebakaran - Mobil Pemadam Kebakaran', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 1110000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Modal Alat Pemadam Kebakaran - Mobil Pemadam Kebakaran (Kapasitas Tangki 800 Liter)', '1. Chasis menggunakan merek TOYOTA dengan tipe HILUX RANGGA dan jumlah roda 4 dengan transmisi Manual 2. Cabin kendaraan tipe Single Cabin dengan kapasitas 3 orang beserta pengemudi 3. Rangka body menggunakan besi profil siku Galvanis ukuran 30 mm x 30 mm dengan ketebalan minimal 3 mm dan Canal UNP 6,5 ketebalan minimal 3 mm 4. Penutup Rangka menggunakan bahan plat alumunium 2 lapis/ alumunium composite dengan ketebalan minimal 4 mm dan pada saat pemasangan di beri lem silicon pada rangka dan lembaran penutup body agar lebih kuat dan meredam getaran 5. Dilengkapi dengan kompartemen terpisah dibagian depan/belakang kendaraan dan terdapat lampu penerangan untuk kompartemen dan ruang pompa 6. Kapasitas Tangki Air 800 Liter Air menggunakan bahan Plat Carbon Steel dengan ketebalan minimal 2 mm untuk dinding dan 3 mm untuk lantai serta menggunakan sistem Dip Galvanized untuk lapisan anti karat, penutup atap tangki menggunakan plat Bordes Carbon Steel dengan ketebalan minimal 3 mm 7. Memiliki 1 Saluran pengisian dari Hydrant ukuran 2,5”, 1 saluran pengisian dari pompa ukuran 2”, 1 drainner ukuran 1,5”, 1 saringan dalam tangki untuk menyaring kotoran, 1 lubang suction ukuran 3”, 1 saluran lubang overflow ukuran 2,5”, dan Manhole/Lubang dibagian atap tangki untuk akses keluar masuk saat maintenance dan untuk memudahkan mengontrol isi air ditangki dari atas 8. Sistem Pemipaan menggunakan bahan Pipa SCH 40 yang dilapisi dengan lapisan anti karat (Hot Dip Galvanized) 9. Panel Kontrol (Control Panel) terletak pada samping kanan dan kiri kendaraan dan dilengkapi dengan : - 1 Saluran pengisian dari pompa 2,5” - 1 Saluran suction 2,5” - 2 Saluran discharge 2,5” - 1 Vacuum Gauge - 1 Pressure Gauge - 1 Indicator Water Level - 1 Unit Valve Fill Water Tank - 1 Unit Valve Water From Tank 10. Pompa Pemadam menggunakan Pompa Portable bertenaga minimal 13 HP dengan suction 2,5” dan discharge 1,5” dan menggunakan bahan Aluminium yang tahan korosi 11. Seluruh bagian kendaraan dicat dengan menggunakan cat khusus jenis polyurethane dengan kualitas yang bagus 12. Terdapat Turret Monitor dengan ukuran 1,5” yang terletak diatas pada bagian body kendaraan menggunakan bahan anti karat dan dapat digerakkan secara manual dengan rotasi 360° dengan sudut elevasi 90° keatas dan 45° kebawah 13. Peralatan dan Sistem Kelistrikan menggunakan socket yang tahan air dan debu dan dilengkapi dengan: - Lampu Rotary Lightbar - Lampu Sorot - Lampu Strobo - Lampu LED untuk Kompartemen - Worklamp LED - Tail Light LED - Radio Rig - Handy Talky - Public Address 14. Peralatan kendaraan : - Toolkit Set - Roda Ganti / Ban Serep - Segitiga Pengaman - Dongkrak - Ganjal Ban - Bumper belakang yang terbuat dari pipa dan plat carbon steel - Tangga untuk akses ke atas kendaraan - Hand Rail 15. Peralatan Pemadam Kebakaran: - Suction Hose (selang hisap) ukuran 2 inch x 2 Meter - Strainer/Saringan selang hisap - Kunci selang hisap - Selang Pemadam Kebakaran 1,5 inch ukuran 20 Meter - Pistol Grip Nozzle 1,5 inch - Tangga Pemadam Kebakaran - Hook (Ganco) - Kapak besar - Linggis - APAR dry powder ukuran 6kg - Kotak P3K (First Aid Kit) 16. Menyediakan Layanan After Sales yang meliputi: - Disediakan pelatihan (Training) untuk pengoperasian dan perawatan - Garansi Rangla/Body atau keseluruhan unit minimal selama 1 tahun - Garansi Pompa pemadam dan Priming Pompa minimal selama 1 tahun - Garansi kebocoran tangki minimal selama 5 tahun - Jaminan ketersediaan suku cadang minimal selama 15 tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 565394);
