INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147440', 65147440, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN INDIVIDUAL PENYUSUNAN POLICY BRIEF PEMUTAKHIRAN PETA JALAN TRANSISI ENERGI NASIONAL MENUJU NET ZERO EMISSION 2060 UNTUK KEGIATAN KOORDINASI PENGEMBANGAN PROYEK ENERGI BARU DAN ENERGI TERBARUKAN DALAM TRANSISI ENERGI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup pekerjaan Jasa Konsultan Individual dalam pelaksanaan kegiatan Koordinasi Pengembangan Proyek Energi Baru dan Energi Terbarukan dalam Transisi Energi ini adalah: Menyiapkan dan menganalisis data dan informasi dokumen kebijakan perencanaan pembangunan yang terkait dengan kebijakan pengembangan energi baru dan energi terbarukan dalam transisi energi sebagai bahan penyusunan rancangan teknokratik peta jalan transisi energi nasional menuju NZE 2060; Menyiapkan dan menganalisis data dan informasi sebagai penyusunan dan penelaahan rencana kerja dan anggaran Kementerian/Lembaga tahun 2026 yang terkait dengan kebijakan pengembangan energi baru dan energi terbarukan dalam transisi energi sebagai bahan penyusunan rancangan teknokratik peta jalan transisi energi nasional menuju NZE 2060; Identifikasi program pembangunan nasional yang terkait dengan kebijakan pengembangan energi baru dan energi terbarukan dalam transisi energi sebagai bahan penyusunan rancangan teknokratik peta jalan transisi energi nasional menuju NZE 2060; Menyusun alternatif rekomendasi kebijakan hasil analisis pemangku kebijakan pengembangan energi baru dan energi terbarukan dalam transisi energi sebagai bahan penyusunan rancangan teknokratik peta jalan transisi energi nasional menuju NZE 2060; Melakukan kunjungan lapangan dalam rangka pengumpulan data dan informasi terkait dengan analisis kebijakan transisi energi nasional menuju NZE 2060 yang terkait dengan pengembangan energi baru dan energi terbarukan dalam transisi energi, dibebankan kepada APBN Badan Perencanaan Pembangunan Nasional, Direktorat Sumber Daya Energi Mineral dan Pertambangan Tahun Anggaran 2026 dan sumber pembiayaan lainnya sesuai dengan ketentuan yang berlaku; Menyusun Laporan Analisis kebijakan menyeluruh sebagai bahan pemutakhiran peta jalan transisi energi nasional menuju NZE 2060.', 'Pria/Wanita, pendidikan minimal S2 Ilmu Kebijakan atau Perencanaan Wilayah dan Kota / Planologi; Memiliki pengalaman minimal 3 (tiga) tahun bekerja; Memiliki pengalaman bekerja minimal 1 (satu) tahun pada instansi atau perusahaan yang berkaitan dengan perencanaan pembangunan dan/atau perencanaan kebijakan publik; Memiliki pemahaman yang baik terhadap efisiensi energi, energi terbarukan, dan transisi energi pada konteks kebijakan publik; Memiliki kemampuan dalam menyusun substansi perencanaan dan melakukan pelaporan; Memiliki kemampuan dalam menulis dokumen perencanaan dan dokumen pendukung perencanaan lainnya. Memiliki pengalaman bekerja pada instansi pemerintahan dibuktikan dengan CV', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 568077);
