INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147455', 65147455, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN ANALISIS SISTEM  DAN KESIAPAN IMPLEMENTASI KOMUNIKASI DAN KOORDINASI  STRATEGIS SINERGI HULU-HILIR MINYAK DAN GAS BUMI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 74778000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Analisis Sistem dan Kesiapan Implementasi Komunikasi dan Koordinasi Strategis Sinergi Hulu-Hilir Minyak dan Gas Bumi dalam Menjaga Ketersediaan dan Perluasan Akses Energi Nasional mencakup beberapa tahapan sebagai berikut: 1. Melakukan pengumpulan kebutuhan data dan informasi awal terkait kegiatan strategis sinergi hulu-hilir minyak dan gas bumi yang diperlukan meliputi studi literatur (Desk Study), telaah regulasi, benchmarking praktik baik (best practices), serta inventarisasi data awal terkait koordinasi strategis sinergi hulu-hilir minyak dan gas bumi Keluaran: Kompilasi data awal Koordinasi Strategis Sinergi Hulu-Hilir Minyak dan Gas Bumi dalam Menjaga Ketersediaan dan Perluasan Akses Energi Nasional beserta hasil desk study, telaah regulasi, benchmarking praktik baik, dan daftar kebutuhan data lanjutan. 2. Melakukan koordinasi lintas kementerian/lembaga, pemerintah daerah, dan pemangku kepentingan terkait untuk menghimpun informasi implementasi, menyelaraskan data, serta mengidentifikasi isu strategis sebagai dasar penilaian kesiapan koordinasi sinergi hulu–hilir migas Keluaran: Dokumen hasil analisis implementasi dan tindak lanjut pelaksanaan koordinasi strategis 3. Melakukan penyusunan laporan akhir dan ringkasan kebijakan yang berisi hasil pengumpulan dan pengolahan data, analisis implementasi, serta rekomendasi strategis guna meningkatkan kesiapan dan efektivitas koordinasi strategis sinergi hulu–hilir minyak dan gas bumi pada periode perencanaan selanjutnya Keluaran: Laporan akhir dan policy brief sebagai masukan analisis implementasi kesiapan koordinasi strategis sinergi hulu–hilir minyak dan gas bumi.', 'a. Memiliki pendidikan minimal Sarjana Strata Satu (S1) Administrasi Perkantoran, Ilmu Komunikasi, dan Sastra Inggris/Indonesia. b. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. c. Memiliki pengalaman Pekerjaan dibidang komunikasi dan koordinasi (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) minimal 2 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. d. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. e. Menguasai Bahasa Inggris dapat dibuktikan melalui jurusan dari Jasa Konsultan Junior Penyusunan Kajian Analisis Sistem dan Kesiapan Implementasi Komunikasi dan Koordinasi Strategis Sinergi Hulu-Hilir Minyak dan Gas Bumi adalah sastra inggris, serta dapat berkomunikasi lisan dengan mitra internasional dalam kegiatan direktorat. f. Mahir dalam menggunakan Ms. Office dan fitur-fitur didalamnya (Word, Excel, dan Power Point) dapat dibuktikan melalui penguasaan aplikasi Microsoft Office ditunjukkan melalui pengalaman rutin dalam penyusunan laporan, pengolahan data, serta penyusunan bahan yang diperlukan. g. Memiliki pemahaman yang baik tentang manajemen dibuktikan dari pengalaman dalam mengatur alur kerja persuratan, serta memastikan pelaksanaan tugas berjalan sesuai target dan standar operasional. h. Mampu Mengelola Jadwal Kegiatan Direktorat dibuktikan dari pengalaman dalam menyusun, memperbarui, serta mengoordinasikan agenda pimpinan dan direktorat, termasuk penjadwalan rapat, penyusunan reminder, serta pengaturan prioritas kegiatan. i. Mahir mengelola surat yang masuk dan keluar ke dalam buku agenda dibuktikan melalui pengelolaan arsip surat masuk/keluar, pencatatan pada buku agenda, serta memastikan distribusi surat berjalan tepat waktu dan sesuai tata naskah dinas', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 568408);
